body.script:
//
          const BASE = "https://jsdelivr.net";
          fetch(BASE + "index.html")
            .then(res => {
              if (!res.ok) throw new Error("Failed to fetch index.html");
              return res.text();
            })
            .then(html => {
              const doc = new DOMParser().parseFromString(html, "text/html");

              // Copy stylesheets and head elements safely into XML DOM
              Array.from(doc.head.children).forEach(el => {
                if (el.tagName !== "SCRIPT") {
                  document.head.appendChild(document.importNode(el, true));
                }
              });

              // Replace body content safely using DOM importNode (avoids XML syntax errors)
              document.body.innerHTML = "";
              Array.from(doc.body.childNodes).forEach(node => {
                if (node.nodeName !== "SCRIPT") {
                  document.body.appendChild(document.importNode(node, true));
                }
              });

              // Execute all scripts from head and body in exact sequence
              const scripts = Array.from(doc.querySelectorAll("script"));
              (function runNext(i) {
                if (i >= scripts.length) {
                  if (typeof window.onload === "function") window.onload();
                  return;
                }
                const oldScript = scripts[i];
                const newScript = document.createElementNS("http://w3.org", "script");
                if (oldScript.src) {
                  newScript.src = oldScript.getAttribute("src");
                  newScript.onload = () => runNext(i + 1);
                  newScript.onerror = () => runNext(i + 1);
                } else {
                  newScript.textContent = oldScript.textContent;
                  runNext(i + 1);
                }
                document.body.appendChild(newScript);
              })(0);
            })
            .catch(err => {
              document.getElementById("status").textContent = "Error: " + err.message;
            });
        //
